"""Money helpers."""

import math
from decimal import Decimal
from fractions import Fraction


def _weight_to_fraction(weight):
    """Convert a weight to an exact Fraction.

    Floats use Fraction(value), so the binary value is kept exactly and later
    remainder ties are not decided by float rounding.
    """
    if isinstance(weight, float):
        if not math.isfinite(weight):
            raise ValueError("weight must not be NaN or infinite")
        return Fraction(weight)
    if isinstance(weight, Decimal):
        if not weight.is_finite():
            raise ValueError("weight must not be NaN or infinite")
        return Fraction(weight)
    if isinstance(weight, Fraction):
        return weight
    # bool is a subclass of int, but it is a valid 0/1 weight. total_cents is
    # the input that rejects bool.
    if isinstance(weight, int):
        return Fraction(weight)
    raise ValueError(
        "weight must be int, float, Fraction, or Decimal, "
        f"not {type(weight).__name__}"
    )


def allocate(total_cents, weights):
    """Split total_cents across weights. See TASK.md for the full spec."""
    if isinstance(total_cents, bool) or not isinstance(total_cents, int):
        raise ValueError("total_cents must be an int")

    # Copy first so nothing below can mutate the caller's list.
    parties = list(weights)
    if not parties:
        raise ValueError("weights must be non-empty")

    exact = [_weight_to_fraction(weight) for weight in parties]
    if any(weight < 0 for weight in exact):
        raise ValueError("weight must not be negative")

    total_weight = sum(exact, Fraction(0))
    if total_weight == 0:
        raise ValueError("weights must not all be zero")

    magnitude = -total_cents if total_cents < 0 else total_cents
    floors = []
    remainders = []
    for weight in exact:
        share = Fraction(magnitude) * weight / total_weight
        floor_cents = share.numerator // share.denominator
        floors.append(floor_cents)
        remainders.append(share - floor_cents)

    leftover = magnitude - sum(floors)
    # Largest fractional remainder; ties go to the larger weight, then the lower index.
    order = sorted(
        range(len(exact)),
        key=lambda i: (-remainders[i], -exact[i], i),
    )
    for index in order[:leftover]:
        floors[index] += 1

    if total_cents < 0:
        return [-cents for cents in floors]
    return floors

